// Foja's service worker (generated by integrations/service-worker.mjs at build time).
// Everything is precached on install; requests are answered from the cache first, pages fall
// back to the network and then to the cached copy, so the editor works offline.

const CACHE = "foja-__VERSION__";
const PRECACHE = __PRECACHE__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map((path) => new URL(path, self.registration.scope).href)))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("foja-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET" || new URL(request.url).origin !== self.location.origin) return;
  if (request.mode === "navigate") {
    // Pages: the network when there is one (a new version shows at once), else the cache.
    event.respondWith(
      fetch(request).catch(() =>
        caches.match(request, { ignoreSearch: true, ignoreVary: true }).then((hit) => hit ?? caches.match(new URL("editor/", self.registration.scope).href)),
      ),
    );
    return;
  }
  // Assets have hashed names: the cache is always right for them. `ignoreVary`: module scripts are
  // requested with an Origin header the precache requests did not have.
  event.respondWith(caches.match(request, { ignoreSearch: true, ignoreVary: true }).then((hit) => hit ?? fetch(request)));
});
